/*
 * se_rust_shims.c — Non-inline ("outline") implementations of FORCEINLINE/macro
 * functions that the Rust ntoskrnl-rust crate calls via extern declarations.
 *
 * Only includes SE-specific functions. Common functions (KeEnterCriticalRegion,
 * PsGetCurrentThread, push locks, etc.) are provided by ob/ob_rust_shims.c.
 *
 * Generated by: python -m rustconv shims se (then manually pruned)
 */

